<div><label for="f-loss">Type of loss</label><select id="f-loss" name="loss"><option>Hail</option><option>Wind / tornado / derecho</option><option>Snow load or collapse</option><option>Ice dam / frozen pipe</option><option>Water or sewer backup</option><option>Fire / smoke</option><option>Other</option></select></div>
